#!/usr/bin/env node
import {
  resolveGlob
} from "./chunk-SH5HYKQV.js";
import {
  atomicWrite,
  withFileLock
} from "./chunk-MBLQFY4T.js";
import "./chunk-IWNALT6P.js";
import {
  ExitCode,
  GramCLIError,
  getErrorMessage
} from "./chunk-IXNX2GX7.js";

// src/commands/format.ts
import { defineCommand } from "citty";
import { readFile } from "fs/promises";
import { log } from "@clack/prompts";
import chalk from "chalk";
import pLimit from "p-limit";
import { formatGram, hasChanges, summarizeChanges } from "@gram-lang/format";
var format_default = defineCommand({
  meta: {
    name: "format",
    description: "Format .gram recipe files"
  },
  args: {
    pattern: {
      type: "positional",
      description: "File path or glob pattern (default: **/*.gram)",
      required: false
    },
    check: {
      type: "boolean",
      description: "Check formatting without writing changes (exit 1 if any file needs formatting)",
      default: false
    }
  },
  async run({ args }) {
    const patterns = args._.length > 0 ? args._ : ["**/*.gram"];
    let files;
    try {
      files = await resolveGlob(patterns);
    } catch (err) {
      if (err instanceof GramCLIError) {
        log.error(err.message);
        process.exit(err.exitCode);
      }
      throw err;
    }
    const isCheck = args.check;
    const limit = pLimit(20);
    const results = await Promise.all(
      files.map(
        (file) => limit(async () => {
          let source;
          try {
            source = await readFile(file, "utf-8");
          } catch (err) {
            return {
              file,
              status: "error",
              message: getErrorMessage(err)
            };
          }
          const { content, changes } = formatGram(source);
          if (!hasChanges(changes)) {
            return { file, status: "unchanged" };
          }
          if (!isCheck) {
            await withFileLock(file, () => atomicWrite(file, content));
          }
          return {
            file,
            status: "changed",
            summary: summarizeChanges(changes)
          };
        })
      )
    );
    let needsFormatting = 0;
    console.log();
    for (const result of results) {
      if (result.status === "error") {
        log.error(`Cannot read ${result.file}: ${result.message}`);
        continue;
      }
      if (result.status === "unchanged") {
        console.log(
          `  ${chalk.green("\u2714")} ${chalk.dim(result.file)}  ${chalk.dim("already formatted")}`
        );
        continue;
      }
      needsFormatting++;
      if (isCheck) {
        console.log(
          `  ${chalk.yellow("\u2717")} ${result.file}  ${chalk.dim(result.summary)}`
        );
      } else {
        console.log(
          `  ${chalk.green("\u2714")} ${result.file}  ${chalk.dim(result.summary)}`
        );
      }
    }
    console.log();
    if (isCheck && needsFormatting > 0) {
      log.warn(
        `${needsFormatting} file${needsFormatting > 1 ? "s" : ""} need formatting. Run \`gram format\` to fix.`
      );
      process.exit(ExitCode.Error);
    }
    if (!isCheck && needsFormatting > 0) {
      log.success(
        `Formatted ${needsFormatting} file${needsFormatting > 1 ? "s" : ""}.`
      );
    }
  }
});
export {
  format_default as default
};
